UPDATE S09T001T 
  SET
    JOTAI          = '4'
  , FURIKAEDYDMDD  = #{entity.furikaedydmdd,jdbcType=VARCHAR}
  , KOSHAAPKIHONCD = #{entity.koshaapkihoncd,jdbcType=VARCHAR}
  , KOSHASHOPCD    = #{entity.koshashopcd,jdbcType=VARCHAR}
  , KOSHACD        = #{entity.koshacd,jdbcType=VARCHAR}
  , KSHNSYSTMYMD   = #{entity.kshnsystmymd,jdbcType=VARCHAR}
  , KSHNSYSTMJIKAN = #{entity.kshnsystmjikan,jdbcType=VARCHAR}
  , KSHNUNYOYMD    = #{entity.kshnunyoymd,jdbcType=VARCHAR}
  , KSHNIPADRSE    = #{entity.kshnipadrse,jdbcType=VARCHAR}
  , KSHNPGMID      = #{entity.kshnpgmid,jdbcType=VARCHAR}
WHERE
      APKIHONCD    = #{entity.apkihoncd,jdbcType=VARCHAR}
  AND SHOPCD       = #{entity.shopcd,jdbcType=VARCHAR}
  AND SHIMEDYDM    = #{entity.shimedydm,jdbcType=VARCHAR}
  AND SHIMEDD      = #{entity.shimedd,jdbcType=VARCHAR}
  AND JOTAI        = '3' 
  AND KSIKEKKA     IS NOT NULL 
  AND KSIKKNCD     = #{entity.ksikkncd,jdbcType=VARCHAR}

UPDATE
  S09T001T KRKT 
SET
    JOTAI          = '1'
  , KOSHAAPKIHONCD = #{s09T001TEntity.koshaapkihoncd,jdbcType=VARCHAR}
  , KOSHASHOPCD    = #{s09T001TEntity.koshashopcd,jdbcType=VARCHAR}
  , KOSHACD        = #{s09T001TEntity.koshacd,jdbcType=VARCHAR}
  , KSHNSYSTMYMD   = #{s09T001TEntity.kshnsystmymd,jdbcType=VARCHAR}
  , KSHNSYSTMJIKAN = #{s09T001TEntity.kshnsystmjikan,jdbcType=VARCHAR}
  , KSHNUNYOYMD    = #{s09T001TEntity.kshnunyoymd,jdbcType=VARCHAR}
  , KSHNIPADRSE    = #{s09T001TEntity.kshnipadrse,jdbcType=VARCHAR}
  , KSHNPGMID      = #{s09T001TEntity.kshnpgmid,jdbcType=VARCHAR}
WHERE
      APKIHONCD    = #{s09T001TEntity.apkihoncd,jdbcType=VARCHAR}
  AND SHOPCD       = #{s09T001TEntity.shopcd,jdbcType=VARCHAR}
  AND KSIKKNCD     = #{s09T001TEntity.ksikkncd,jdbcType=VARCHAR}
  AND SHIMEDYDM    = #{s09T001TEntity.shimedydm,jdbcType=VARCHAR}
  AND SHIMEDD      = #{s09T001TEntity.shimedd,jdbcType=VARCHAR}

UPDATE
  S09T001T KRKT 
SET
    JOTAI          = '3'
  , KOSHAAPKIHONCD = #{s09T001TEntity.koshaapkihoncd,jdbcType=VARCHAR}
  , KOSHASHOPCD    = #{s09T001TEntity.koshashopcd,jdbcType=VARCHAR}
  , KOSHACD        = #{s09T001TEntity.koshacd,jdbcType=VARCHAR}
  , KSHNSYSTMYMD   = #{s09T001TEntity.kshnsystmymd,jdbcType=VARCHAR}
  , KSHNSYSTMJIKAN = #{s09T001TEntity.kshnsystmjikan,jdbcType=VARCHAR}
  , KSHNUNYOYMD    = #{s09T001TEntity.kshnunyoymd,jdbcType=VARCHAR}
  , KSHNIPADRSE    = #{s09T001TEntity.kshnipadrse,jdbcType=VARCHAR}
  , KSHNPGMID      = #{s09T001TEntity.kshnpgmid,jdbcType=VARCHAR}
WHERE
      APKIHONCD    = #{s09T001TEntity.apkihoncd,jdbcType=VARCHAR}
  AND SHOPCD       = #{s09T001TEntity.shopcd,jdbcType=VARCHAR}
  AND KSIKKNCD     = #{s09T001TEntity.ksikkncd,jdbcType=VARCHAR}
  AND SHIMEDYDM    = #{s09T001TEntity.shimedydm,jdbcType=VARCHAR}
  AND SHIMEDD      = #{s09T001TEntity.shimedd,jdbcType=VARCHAR}
  AND EXISTS (
    SELECT
      SKSM.SKYSAKICD
    FROM
      S02M017T SKSM
    WHERE
          SKSM.APKIHONCD      = KRKT.APKIHONCD
      AND SKSM.SHOPCD         = KRKT.SHOPCD
      AND SKSM.SKYSAKICD      = KRKT.SKYSAKICD
      AND SKSM.CRDTCRDYUKOKBN  <>  '0'
      AND SKSM.YUKOKBN        = '1'
  )
  AND KSIKIN       > 0

mapper.select:
SELECT * FROM (SELECT KRKT.SHIMEDYDM SHIMEDYDM, KRKT.SHIMEDD SHIMEDD, KRKT.JOTAI JOTAI, CONM.ITEMNM JOTAINM, KRKT.FURIKAEDYDMDD FURIKAEDYDMDD, KRKT.KSIKIN KSIKIN, KRKT.KSIKEKKA KSIKEKKA, SYKM.MOJISETTEIATAI MOJISETTEIATAI, KSKM.KSIKKNNM FROM S09T001T KRKT INNER JOIN S02M013T TKSM ON KRKT.APKIHONCD = TKSM.APKIHONCD AND KRKT.SHOPCD = TKSM.SHOPCD AND KRKT.SKYSAKICD = TKSM.SKYSAKICD LEFT JOIN S02M025T KSKM ON KRKT.APKIHONCD = KSKM.APKIHONCD AND KRKT.SHOPCD = KSKM.SHOPCD AND KRKT.KSIKKNCD = KSKM.KSIKKNCD LEFT JOIN S02M006T SYKM ON KRKT.KSIKEKKA = SYKM.SETTEICD AND SYKM.APKIHONCD = '000' AND SYKM.SHOPCD = '000' AND SYKM.SETTEINO = '086' AND SYKM.RCRDKBN = 'M' LEFT JOIN S01M004T CONM ON KRKT.JOTAI = CONM.SETTEIATAI AND CONM.CONDITIONID = 'CN176' WHERE TKSM.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND TKSM.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND TKSM.TOKUISAKICD = #{tokuisakicd,jdbcType=VARCHAR}
AND KRKT.SHIMEDYDM <= #{shimedydm,jdbcType=VARCHAR}
AND KRKT.YUKOKBN = '1' ORDER BY SHIMEDYDM DESC, SHIMEDD DESC ) WHERE ROWNUM <= 2

