mapper.select:
SELECT
  COUNT(*) AS RECORD_COUNT
FROM
  S09T001T KRKT
INNER JOIN S02M017T SKSM
  ON (
            SKSM.APKIHONCD      = KRKT.APKIHONCD
        AND SKSM.SHOPCD         = KRKT.SHOPCD
        AND SKSM.SKYSAKICD      = KRKT.SKYSAKICD
        AND SKSM.CRDTCRDYUKOKBN = '0'
     )
WHERE
      KRKT.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR}
  AND KRKT.SHOPCD    = #{shopcd,jdbcType=VARCHAR}
  AND KRKT.KSIKKNCD  = #{kinyukkncd,jdbcType=VARCHAR}
  AND KRKT.SHIMEDYDM = #{shimedydm,jdbcType=VARCHAR}
